// Simplified LRU with array (educational)
#define CAP 3
int keys[CAP],vals[CAP],order[CAP],ord=0,n=0;
void put(int k,int v){for(int i=0;i<n;i++)if(keys[i]==k){vals[i]=v;order[i]=ord++;return;}if(n<CAP){keys[n]=k;vals[n]=v;order[n]=ord++;n++;}else{int mn=0;for(int i=1;i<n;i++)if(order[i]<order[mn])mn=i;keys[mn]=k;vals[mn]=v;order[mn]=ord++;}}
int get(int k){for(int i=0;i<n;i++)if(keys[i]==k){order[i]=ord++;return vals[i];}return -1;}

